    18	        public ScriptedListener(Func<TcpClient, CancellationToken, Task> onConnection)
    19	        {
    20	            _listener = new TcpListener(IPAddress.Loopback, 0);
    21	            _listener.Start();
    22	            Port = ((IPEndPoint)_listener.LocalEndpoint).Port;
    23	            _accepting = Task.Run(async () =>
    24	            {
    25	                while (!_stop.IsCancellationRequested)
    26	                {
    27	                    using var client = await _listener.AcceptTcpClientAsync(_stop.Token);
    28	                    await onConnection(client, _stop.Token);
    29	                }
    30	            });
    31	        }
