    38	            {
    39	                await _accepting;
    40	            }
    41	            catch (OperationCanceledException)
    42	            {
    43	                // Listener shutdown.
    44	            }
    45	            catch (SocketException)
    46	            {
    47	                // Accept aborted by Stop.
    48	            }
    49	
    50	            _stop.Dispose();
    51	        }
