    55	    /// <summary>
    56	    /// Translates the topology into Aspire resources on <paramref name="builder"/>. Separated from
    57	    /// <see cref="RunAsync"/> so the built model can be inspected in tests without running DCP.
    58	    /// </summary>
    59	    internal static void Apply(
    60	        IDistributedApplicationBuilder builder, SystemTopology topology, string generatedRoot)
    61	    {
    62	        var componentsPath = Path.Combine(generatedRoot, GeneratedArtifacts.ComponentsDir);
    63	        var configDir = Path.Combine(generatedRoot, GeneratedArtifacts.ConfigDir);
    64	
    65	        // A plain Redis container rather than AddRedis: the generated pub/sub YAML speaks
    66	        // passwordless to localhost:6380, while AddRedis injects a generated password.
    67	        var redis = builder
    68	            .AddContainer("redis", "docker.io/library/redis", "7")
    69	            .WithEndpoint(port: RedisPort, targetPort: 6379);
    70	        WithTcpReadiness(builder, redis, RedisPort, TcpReadyHealthCheck.RedisHandshake);
    71	
    72	        // Everything a sidecar dials during component init. Sidecars must wait for these to be
    73	        // *ready* (not merely running) — daprd treats a failed component init as fatal, so racing
    74	        // a still-starting backend kills the sidecar. localhost:6380 is DCP's endpoint proxy,
    75	        // which accepts connections from host start, so the probe must demand a PONG rather
    76	        // than settle for an open socket.
    77	        var backends = new List<IResourceBuilder<IResource>> { redis };
    78	        var backendProbes = new List<TcpReadyHealthCheck>
    79	        {
    80	            new("localhost", RedisPort, TcpReadyHealthCheck.RedisHandshake),
    81	        };
    82	
    83	        // Filled after the component loop; the hook closure only reads it at runtime.
    84	        var sidecarWaits = new Dictionary<string, string[]>(StringComparer.Ordinal);
    85	
    86	        // The Dapr toolkit materializes each sidecar as a separate "<component>-dapr-cli" executable
    87	        // that does not carry wait annotations, so WaitFor cannot gate it. Hold its start here until
    88	        // every backend port answers and, for publishers, until every subscriber sidecar is running.
    89	        builder.Eventing.Subscribe<BeforeResourceStartedEvent>(async (evt, cancellationToken) =>
    90	        {
    91	            if (!evt.Resource.Name.EndsWith("-dapr-cli", StringComparison.Ordinal))
    92	            {
    93	                return;
    94	            }
    95	
    96	            foreach (var probe in backendProbes)
    97	            {
    98	                await probe.WaitUntilReadyAsync(TimeSpan.FromMinutes(3), cancellationToken).ConfigureAwait(false);
    99	            }
   100	
   101	            if (sidecarWaits.TryGetValue(evt.Resource.Name, out var subscriberSidecars))
   102	            {
   103	                var notifications = evt.Services.GetRequiredService<ResourceNotificationService>();
   104	                foreach (var sidecar in subscriberSidecars)
   105	                {
   106	                    await notifications
   107	                        .WaitForResourceAsync(sidecar, KnownResourceStates.Running, cancellationToken)
   108	                        .ConfigureAwait(false);
   109	                }
   110	            }
   111	        });
   112	
   113	        var resources = new Dictionary<string, IResourceBuilder<IResource>>(StringComparer.Ordinal);
   114	        var waiters = new Dictionary<string, Action<IResourceBuilder<IResource>>>(StringComparer.Ordinal);
   115	        var unresolved = new List<string>();
   116	        foreach (var component in topology.Components)
   117	        {
   118	            // Each integration gets its own staged component set: its local files plus the
   119	            // generated system overlay, at a stable inspectable path under obj/.
   120	            var stagedPath = ComponentOverlay.Stage(builder.AppHostDirectory, component.Name, componentsPath);
   121	
   122	            var projectPath = ProjectConvention.Resolve(builder.AppHostDirectory, component.Name);
   123	            if (!File.Exists(projectPath))
   124	            {
   125	                unresolved.Add($"{component.Name} (expected {projectPath})");
   126	                continue;
   127	            }
   128	
   129	            var project = builder.AddProject(component.Name, projectPath);
   130	            if (component.Schedule is null)
   131	            {
   132	                // The endpoint makes Aspire allocate a port and inject ASPNETCORE_URLS (without it
   133	                // every Kestrel binds the 5000 default) and gives the Dapr sidecar its app-port.
   134	                // A scheduled component is a run-to-completion job that receives no inbound
   135	                // delivery, so it gets neither.
   136	                project = project.WithHttpEndpoint();
   137	            }
   138	            else
   139	            {
   140	                AddRunNowCommand(project, component.Name);
   141	            }
   142	
   143	            Wire(project, component, stagedPath, configDir, backends);
   144	            resources[component.Name] = project;
   145	            waiters[component.Name] = dependency => project.WaitFor(dependency);
   146	        }
   147	
   148	        RegisterDaprSidecarRecovery(builder, topology, backendProbes);
   149	        RegisterScheduler(builder, topology);
   150	
   151	        if (unresolved.Count > 0)
   152	        {
   153	            throw new InvalidOperationException(
   154	                $"No project found for these components by folder convention: {string.Join(", ", unresolved)}. " +
   155	                "Create the project next to the SystemHost.");
   156	        }
   157	
   158	        // Subscribers start first, so a publisher's first message finds a registered
   159	        // subscription. Nobody declares this: it is derived from who publishes and who
   160	        // subscribes each topic. Publish/subscribe cycles cannot be ordered — skip entirely
   161	        // rather than deadlock.
   162	        var precedence = SubscriberPrecedence(topology);
   163	        if (HasCycle(precedence))
   164	        {
   165	            Console.Error.WriteLine(
   166	                "intropy: the topology's topics form a publish/subscribe cycle; " +
   167	                "skipping subscriber-first startup ordering.");
   168	            return;
   169	        }
   170	
   171	        foreach (var (publisher, subscribers) in precedence)
   172	        {
   173	            if (!waiters.TryGetValue(publisher, out var wait))
   174	            {
   175	                continue;
   176	            }
   177	
   178	            var materialized = subscribers.Where(resources.ContainsKey).ToArray();
   179	            foreach (var subscriber in materialized)
   180	            {
   181	                wait(resources[subscriber]);
   182	            }
   183	
   184	            if (materialized.Length > 0)
   185	            {
   186	                sidecarWaits[$"{publisher}-dapr-cli"] =
   187	                    [.. materialized.Select(s => $"{s}-dapr-cli")];
   188	            }
   189	        }
   190	    }
