   192	    /// <summary>
   193	    /// Registers the <see cref="ComponentScheduler"/> when any component declares a schedule.
   194	    /// Keyed off <c>Schedule</c>, not the component kind — the scheduler is kind-blind.
   195	    /// </summary>
   196	    private static void RegisterScheduler(IDistributedApplicationBuilder builder, SystemTopology topology)
   197	    {
   198	        var scheduled = topology.Components
   199	            .Where(c => c.Schedule is not null)
   200	            .Select(c => new ScheduledComponent(c.Name, c.Schedule!))
   201	            .ToArray();
