   207	        builder.Services.TryAddSingleton(TimeProvider.System);
   208	        builder.Services.AddSingleton<IReadOnlyList<ScheduledComponent>>(scheduled);
   209	        builder.Services.TryAddSingleton<IResourceLifecycle, AspireResourceLifecycle>();
   210	        builder.Services.AddSingleton<ComponentScheduler>();
   211	        builder.Services.AddHostedService(sp => sp.GetRequiredService<ComponentScheduler>());
