   214	    /// <summary>
   215	    /// Registers recovery for long-running components' Dapr sidecars. The normal pre-start gate
   216	    /// prevents the common race; recovery covers the remaining interval where a backend passes
   217	    /// TCP readiness but daprd's component initialization still fails. Scheduled components'
   218	    /// sidecars are excluded: the scheduler owns their stop/start lifecycle.
   219	    /// </summary>
   220	    private static void RegisterDaprSidecarRecovery(
   221	        IDistributedApplicationBuilder builder, SystemTopology topology,
   222	        IReadOnlyList<TcpReadyHealthCheck> backendProbes)
   223	    {
   224	        var schedulerOwned = topology.Components
   225	            .Where(c => c.Schedule is not null)
   226	            .Select(c => $"{c.Name}-dapr-cli")
   227	            .ToHashSet(StringComparer.Ordinal);
   228	        builder.Services.AddSingleton(new DaprSidecarRecoveryOptions(schedulerOwned));
   229	        builder.Services.TryAddSingleton(TimeProvider.System);
   230	        builder.Services.TryAddSingleton<IResourceLifecycle, AspireResourceLifecycle>();
   231	        builder.Services.AddSingleton<IResourceStateMonitor, AspireResourceStateMonitor>();
   232	        builder.Services.AddSingleton<IBackendReadiness>(
   233	            new BackendReadiness(backendProbes.Cast<IBackendReadiness>().ToArray()));
   234	        builder.Services.AddSingleton<DaprSidecarRecovery>();
   235	        builder.Services.AddHostedService(sp => sp.GetRequiredService<DaprSidecarRecovery>());
   236	    }
