   257	    /// <summary>
   258	    /// Which components each publisher must wait for: every subscriber of every topic it
   259	    /// publishes. Self-loops (a component consuming its own topic) are not orderable edges.
   260	    /// </summary>
   261	    private static Dictionary<string, HashSet<string>> SubscriberPrecedence(SystemTopology topology)
   262	    {
   263	        var precedence = new Dictionary<string, HashSet<string>>(StringComparer.Ordinal);
   264	        foreach (var topic in topology.Topics)
   265	        {
   266	            foreach (var publisher in topic.Publishers)
   267	            {
   268	                foreach (var subscriber in topic.Subscribers)
   269	                {
   270	                    if (string.Equals(publisher, subscriber, StringComparison.Ordinal))
   271	                    {
   272	                        continue;
   273	                    }
   274	
   275	                    if (!precedence.TryGetValue(publisher, out var subscribers))
   276	                    {
   277	                        precedence[publisher] = subscribers = new HashSet<string>(StringComparer.Ordinal);
   278	                    }
   279	
   280	                    subscribers.Add(subscriber);
   281	                }
   282	            }
   283	        }
   284	
   285	        return precedence;
   286	    }
