   288	    private static bool HasCycle(Dictionary<string, HashSet<string>> edges)
   289	    {
   290	        var state = new Dictionary<string, int>(StringComparer.Ordinal); // 1 = visiting, 2 = done
   291	
   292	        bool Visit(string node)
   293	        {
   294	            if (state.TryGetValue(node, out var seen))
   295	            {
   296	                return seen == 1;
   297	            }
   298	
   299	            state[node] = 1;
   300	            if (edges.TryGetValue(node, out var next) && next.Any(Visit))
   301	            {
   302	                return true;
   303	            }
   304	
   305	            state[node] = 2;
   306	            return false;
   307	        }
   308	
   309	        return edges.Keys.Any(Visit);
   310	    }
