   312	    private static void WithTcpReadiness(
   313	        IDistributedApplicationBuilder builder, IResourceBuilder<ContainerResource> container, int port,
   314	        ReadOnlyMemory<byte> handshake = default)
   315	    {
   316	        var key = $"{container.Resource.Name}-tcp-ready";
   317	        builder.Services.AddHealthChecks().AddCheck(key, new TcpReadyHealthCheck("localhost", port, handshake));
   318	        container.WithHealthCheck(key);
   319	    }
