   321	    private static void Wire<T>(
   322	        IResourceBuilder<T> resource,
   323	        ComponentModel component,
   324	        string resourcesPath,
   325	        string configDir,
   326	        IReadOnlyList<IResourceBuilder<IResource>> backends)
   327	        where T : IResourceWithEnvironment, IResourceWithWaitSupport
   328	    {
   329	        resource
   330	            .WithDaprSidecar(sidecar =>
   331	            {
   332	                sidecar.WithOptions(new DaprSidecarOptions
   333	                {
   334	                    AppId = component.Name,
   335	                    ResourcesPaths = [resourcesPath],
   336	                });
   337	                foreach (var backend in backends)
   338	                {
   339	                    sidecar.WaitFor(backend);
   340	                }
   341	            })
   342	            .WithEnvironment("INTROPY__COMPONENT", component.Name)
   343	            .WithEnvironment("INTROPY__CONFIG", Path.Combine(configDir, $"{component.Name}.intropy.json"));
   344	
   345	        foreach (var backend in backends)
   346	        {
   347	            resource.WaitFor(backend);
   348	        }
   349	    }
   350	}
