   105	/// service only owns the re-runs. Ticks fire in local time (the developer's wall clock,
   106	/// unlike Kubernetes' UTC default), a tick that lands while the previous run is still in
   107	/// progress is skipped with a warning (concurrencyPolicy: Forbid), and the sidecar is
   108	/// started before the app because a run-to-completion block shuts its sidecar down when
   109	/// it exits. See decision 0010.
   110	/// </summary>
   111	internal sealed class ComponentScheduler(
   112	    IReadOnlyList<ScheduledComponent> components,
   113	    IResourceLifecycle lifecycle,
   114	    TimeProvider timeProvider,
   115	    ILogger<ComponentScheduler> logger) : BackgroundService
   116	{
   117	    private static readonly TimeSpan s_sidecarReadyTimeout = TimeSpan.FromMinutes(3);
   118	
   119	    private readonly ConcurrentDictionary<string, SemaphoreSlim> _gates = new(StringComparer.Ordinal);
   120	
   121	    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
   122	    {
   123	        var loops = new List<Task> { WatchQuietlyAsync(stoppingToken) };
   124	        loops.AddRange(components.Select(component => RunScheduleLoopAsync(component, stoppingToken)));
   125	        await Task.WhenAll(loops).ConfigureAwait(false);
   126	    }
   127	
   128	    /// <summary>
   129	    /// Starts the component's sidecar + app resource pair, unless the previous run is still
   130	    /// in progress (skipped with a warning). Shared by cron ticks and the dashboard's
   131	    /// "Run now" command.
   132	    /// </summary>
   133	    internal async Task TriggerAsync(string component, string reason, CancellationToken cancellationToken)
   134	    {
   135	        var gate = _gates.GetOrAdd(component, _ => new SemaphoreSlim(1, 1));
   136	        if (!await gate.WaitAsync(0, cancellationToken).ConfigureAwait(false))
   137	        {
   138	            logger.LogWarning(
   139	                "intropy-schedule: skipping {Reason} for {Component}: a trigger is already executing",
   140	                reason, component);
   141	            return;
   142	        }
   143	
   144	        try
   145	        {
   146	            if (!lifecycle.IsStartable(component))
   147	            {
   148	                logger.LogWarning(
   149	                    "intropy-schedule: skipping {Reason} for {Component}: the previous run is still in progress",
   150	                    reason, component);
   151	                return;
   152	            }
   153	
   154	            // The run-to-completion block shut its sidecar down when it exited, so bring
   155	            // the sidecar back first — daprd must be accepting connections before the app
   156	            // starts, or the app's first sidecar call fails.
   157	            var sidecar = $"{component}-dapr-cli";
