   159	            {
   160	                if (!await StartResourceAsync(sidecar, cancellationToken).ConfigureAwait(false))
   161	                {
   162	                    logger.LogError(
   163	                        "intropy-schedule: could not start sidecar {Sidecar}; abandoning {Reason} for {Component}",
   164	                        sidecar, reason, component);
   165	                    return;
   166	                }
   167	
   168	                if (!await lifecycle.WaitUntilRunningAsync(sidecar, s_sidecarReadyTimeout, cancellationToken)
   169	                        .ConfigureAwait(false))
   170	                {
   171	                    logger.LogError(
   172	                        "intropy-schedule: sidecar {Sidecar} did not reach Running within {Timeout}; " +
   173	                        "abandoning {Reason} for {Component}",
   174	                        sidecar, s_sidecarReadyTimeout, reason, component);
   175	                    return;
   176	                }
   177	            }
   178	
   179	            if (!await StartResourceAsync(component, cancellationToken).ConfigureAwait(false))
   180	            {
   181	                logger.LogError("intropy-schedule: could not start {Component} ({Reason})", component, reason);
   182	                return;
   183	            }
   184	
   185	            logger.LogInformation("intropy-schedule: triggered {Component} ({Reason})", component, reason);
   186	        }
   187	        finally
   188	        {
   189	            gate.Release();
   190	        }
   191	    }
   192	
   193	    private async Task<bool> StartResourceAsync(string resourceName, CancellationToken cancellationToken)
   194	    {
   195	        // Start is right for a terminal/never-started resource; fall back to Restart to
   196	        // absorb state races between our snapshot and DCP's.
   197	        return await lifecycle.ExecuteAsync(resourceName, KnownResourceCommands.StartCommand, cancellationToken)
   198	                   .ConfigureAwait(false)
   199	               || await lifecycle.ExecuteAsync(resourceName, KnownResourceCommands.RestartCommand, cancellationToken)
   200	                   .ConfigureAwait(false);
   201	    }
   202	
   203	    private async Task RunScheduleLoopAsync(ScheduledComponent component, CancellationToken stoppingToken)
   204	    {
   205	        try
   206	        {
   207	            while (!stoppingToken.IsCancellationRequested)
   208	            {
   209	                var now = timeProvider.GetUtcNow();
   210	                var next = ScheduleTickPlanner.NextOccurrence(component.Cron, now, TimeZoneInfo.Local);
   211	                if (next is null)
   212	                {
   213	                    logger.LogWarning(
   214	                        "intropy-schedule: {Component}'s schedule '{Cron}' never fires again; stopping its loop",
   215	                        component.Name, component.Cron);
   216	                    return;
   217	                }
   218	
   219	                logger.LogInformation(
   220	                    "intropy-schedule: {Component} next run at {Next:o} ({Cron})",
   221	                    component.Name, next.Value.ToLocalTime(), component.Cron);
   222	
   223	                var delay = next.Value - now;
   224	                if (delay > TimeSpan.Zero)
   225	                {
   226	                    await Task.Delay(delay, timeProvider, stoppingToken).ConfigureAwait(false);
   227	                }
   228	
   229	                await TriggerAsync(component.Name, "cron tick", stoppingToken).ConfigureAwait(false);
   230	            }
   231	        }
   232	        catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
   233	        {
   234	            // Host shutdown.
   235	        }
   236	    }
   237	
   238	    private async Task WatchQuietlyAsync(CancellationToken stoppingToken)
   239	    {
   240	        try
   241	        {
   242	            await lifecycle.WatchAsync(stoppingToken).ConfigureAwait(false);
   243	        }
   244	        catch (OperationCanceledException) when (stoppingToken.IsCancellationRequested)
   245	        {
   246	            // Host shutdown.
   247	        }
   248	    }
   249	}
