    59	    private static readonly TimeSpan s_backendReadyTimeout = TimeSpan.FromMinutes(3);
    60	
    61	    // DCP reports an executable as Running the moment its process launches, not when it is
    62	    // healthy — daprd lives ~1s before a fatal component-init exit. Only a stay in Running at
    63	    // least this long counts as having actually run; a scheduled sidecar that legitimately
    64	    // completes faster costs at most MaxAttemptsPerSidecar spurious restarts.
    65	    private static readonly TimeSpan s_minHealthyRunningDuration = TimeSpan.FromSeconds(10);
    66	
    67	    private readonly ConcurrentDictionary<string, int> _attempts = new(StringComparer.Ordinal);
