    86	    internal async Task HandleStateUpdateAsync(ResourceStateUpdate update, CancellationToken cancellationToken)
    87	    {
    88	        if (!update.ResourceName.EndsWith("-dapr-cli", StringComparison.Ordinal))
    89	        {
    90	            return;
    91	        }
    92	
    93	        // A scheduled component's sidecar is scheduler-owned: the run-to-completion block shuts
    94	        // its sidecar down after every run and the scheduler restarts it on the next tick
    95	        // (decision 0010), so its exits are lifecycle, not failure — however quick the run.
    96	        if (options.SchedulerOwnedSidecars.Contains(update.ResourceName))
    97	        {
    98	            return;
    99	        }
