   101	        if (string.Equals(update.State, KnownResourceStates.Running, StringComparison.Ordinal))
   102	        {
   103	            // Overwrite (not TryAdd): after a recovery restart the fresh instance's clock must
   104	            // start over, or its own early crash would be judged by the previous run's stamp.
   105	            _runningSince[update.ResourceName] = time.GetTimestamp();
   106	            return;
   107	        }
