   109	        // A normal scheduled sidecar exits after its app completes — but only a sustained stay
   110	        // in Running proves that, so a component-init crash a moment after launch still recovers.
   111	        var ranHealthily = _runningSince.TryGetValue(update.ResourceName, out var since)
   112	            && time.GetElapsedTime(since) >= s_minHealthyRunningDuration;
