   121	        var gate = _gates.GetOrAdd(update.ResourceName, _ => new SemaphoreSlim(1, 1));
   122	        if (!await gate.WaitAsync(0, cancellationToken).ConfigureAwait(false))
   123	        {
   124	            return;
   125	        }
   126	
   127	        try
   128	        {
   129	            var attempt = _attempts.AddOrUpdate(update.ResourceName, 1, (_, prior) => prior + 1);
   130	            if (attempt > MaxAttemptsPerSidecar)
   131	            {
   132	                logger.LogError(
   133	                    "intropy-dapr: {Sidecar} exhausted {MaxAttempts} recovery attempts; inspect its component configuration",
   134	                    update.ResourceName, MaxAttemptsPerSidecar);
   135	                return;
   136	            }
   137	
   138	            logger.LogWarning(
   139	                "intropy-dapr: {Sidecar} terminated before completing component initialization; waiting for backends before recovery attempt {Attempt}/{MaxAttempts}",
   140	                update.ResourceName, attempt, MaxAttemptsPerSidecar);
   141	            await backendReadiness.WaitUntilReadyAsync(s_backendReadyTimeout, cancellationToken).ConfigureAwait(false);
   142	
   143	            // FailedToStart normally accepts Restart. Start is a state-race fallback when DCP
   144	            // has already moved the resource to a startable terminal state.
   145	            var recovered = await lifecycle
   146	                .ExecuteAsync(update.ResourceName, KnownResourceCommands.RestartCommand, cancellationToken)
   147	                .ConfigureAwait(false)
   148	                || await lifecycle
   149	                    .ExecuteAsync(update.ResourceName, KnownResourceCommands.StartCommand, cancellationToken)
   150	                    .ConfigureAwait(false);
