   152	            {
   153	                logger.LogWarning(
   154	                    "intropy-dapr: recovery command for {Sidecar} was unavailable or failed (attempt {Attempt}/{MaxAttempts})",
   155	                    update.ResourceName, attempt, MaxAttemptsPerSidecar);
   156	            }
   157	        }
   158	        catch (OperationCanceledException) when (cancellationToken.IsCancellationRequested)
   159	        {
   160	            throw;
   161	        }
   162	        catch (Exception ex)
   163	        {
   164	            logger.LogWarning(ex, "intropy-dapr: unable to recover {Sidecar}", update.ResourceName);
   165	        }
