    13	/// Docker Desktop port proxy and Aspire's DCP endpoint proxy accept connections before the
    14	/// backend listens — DCP holds them open in silence, so even "connection survives a read
    15	/// window" passes against a proxy whose backend is down. When the probed protocol lets the
    16	/// client speak first, pass its opening bytes as <paramref name="handshake"/>: readiness then
    17	/// requires an actual response, which only the real backend can produce. Without a handshake,
    18	/// silence within the read window still counts as ready (a listener with no banner).
    19	/// </summary>
    20	internal sealed class TcpReadyHealthCheck(string host, int port, ReadOnlyMemory<byte> handshake = default)
    21	    : IHealthCheck, IBackendReadiness
    22	{
    23	    private static readonly TimeSpan s_readWindow = TimeSpan.FromMilliseconds(750);
    24	
    25	    /// <summary>The inline RESP command "PING\r\n"; a ready Redis answers it with +PONG.</summary>
    26	    public static ReadOnlyMemory<byte> RedisHandshake { get; } = "PING\r\n"u8.ToArray();
    27	
    28	    /// <summary>Polls until the port is ready, throwing if it never becomes so.</summary>
    29	    public async Task WaitUntilReadyAsync(TimeSpan timeout, CancellationToken cancellationToken)
    30	    {
    31	        using var deadline = CancellationTokenSource.CreateLinkedTokenSource(cancellationToken);
    32	        deadline.CancelAfter(timeout);
    33	        try
    34	        {
    35	            while (true)
    36	            {
    37	                var result = await CheckHealthAsync(new HealthCheckContext(), deadline.Token).ConfigureAwait(false);
    38	                if (result.Status == HealthStatus.Healthy)
    39	                {
    40	                    return;
    41	                }
    42	
    43	                await Task.Delay(TimeSpan.FromSeconds(1), deadline.Token).ConfigureAwait(false);
    44	            }
    45	        }
    46	        catch (OperationCanceledException) when (!cancellationToken.IsCancellationRequested)
    47	        {
    48	            throw new InvalidOperationException($"{host}:{port} did not become ready within {timeout}.");
    49	        }
    50	    }
    51	
    52	    public async Task<HealthCheckResult> CheckHealthAsync(
    53	        HealthCheckContext context, CancellationToken cancellationToken = default)
    54	    {
    55	        try
    56	        {
    57	            using var client = new TcpClient();
    58	            await client.ConnectAsync(host, port, cancellationToken).ConfigureAwait(false);
    59	            var stream = client.GetStream();
    60	            if (!handshake.IsEmpty)
    61	            {
    62	                await stream.WriteAsync(handshake, cancellationToken).ConfigureAwait(false);
    63	            }
